104	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
105	            counts.getOrDefault(person.getId(), Map.of()).entrySet().stream()
106	                    .filter(e -> e.getValue() >= 2)
107	                    .sorted(Map.Entry.<Key, Long>comparingByKey(Comparator.comparing(Key::date)
108	                            .thenComparing(Key::amount)))
109	                    .forEach(e -> out.add(person.getName() + " " + e.getKey().date() + " "
110	                            + e.getKey().amount().toPlainString() + " x" + e.getValue()));
111	        }
112	        return out;
113	    }
