162	    /** Share the claim with another person on the sheet: they hold {@code share} percent (more than 0.00)
163	     * of what is due on it. Refused when the person is the claim's own, already holds a share of it, when
164	     * its shares would total more than 100.00, and when the claim is SETTLED, VOID or DELETED. */
165	    @Transactional
166	    public Claim share(String sheetId, String user, long claimId, long personId, BigDecimal share) {
167	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
168	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
169	                || claim.getStatus() == ClaimStatus.DELETED) {
170	            throw new ClaimShareException();
171	        }
172	        Person holder = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
173	        if (share.signum() <= 0 || holder.getId().equals(claim.getPersonId())) throw new ClaimShareException();
174	        List<ClaimShare> held = shares.findByClaimIdOrderByIdAsc(claim.getId());
175	        if (held.stream().anyMatch(s -> s.getPersonId().equals(holder.getId()))) throw new ClaimShareException();
176	        BigDecimal total = held.stream().map(ClaimShare::getShare).reduce(share, BigDecimal::add);
177	        if (total.compareTo(BigDecimal.valueOf(100)) > 0) throw new ClaimShareException();
178	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
179	                .orElseThrow(PersonNotFoundException::new);
180	        RollupService.Snapshot before = rollup.snapshot(sheetId);
181	        ClaimShare given = shares.saveAndFlush(new ClaimShare(sheetId, claim.getId(), holder.getId(), share));
182	        record("CLAIM_SHARED", user, person, claim, null, "with=" + holder.getName(), "share=" + given.shareText());
183	        rollup.recordSince(sheetId, user, before);
184	        return claim;
185	    }
