187	    /** Add a line to a DRAFT claim: {@code label} (not blank), {@code qty} (at least 1) of {@code unit}
188	     * each; the claim's amount becomes its lines' quantities times their unit amounts, added up. It counts
189	     * as an edit of the claim. Refused when the claim is not a DRAFT, when its due-by is in a closed period
190	     * and when another user's editor holds its lock. */
191	    @Transactional
192	    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
193	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
194	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
195	        refuseClosed(sheetId, claim.getDueBy());
196	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
197	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
198	                .orElseThrow(PersonNotFoundException::new);
199	        RollupService.Snapshot before = rollup.snapshot(sheetId);
200	        lines.saveAndFlush(new ClaimLine(claim.getId(), label, qty, unit.setScale(2)));
201	        List<ClaimLine> all = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
202	        BigDecimal total = ClaimLine.totalOf(all);
203	        if (total.precision() - total.scale() > 10) throw new ClaimLinedAmountException();
204	        claim.setAmount(total);
205	        claim.setEditedBy(user);
206	        claims.flush();
207	        ClaimLine line = all.get(all.size() - 1);
208	        record("CLAIM_LINE_ADDED", user, person, claim, claim.getNumber(), "label=" + line.getLabel(),
209	                "qty=" + line.getQty(), "unit=" + line.unitText());
210	        rollup.recordSince(sheetId, user, before);
211	        return claim;
212	    }
