214	    /** Make the claims, settled (or left PENDING) by one bulk settle, the sheet's next settle batch,
215	     * returning them with its number, in the order given; records BATCH_SETTLED with the batch's number,
216	     * how many claims it has and the frozen figures of those SETTLED added up. */
217	    @Transactional
218	    public List<Claim> settleBatch(String sheetId, String user, List<Claim> settled) {
219	        int batch = sheets.nextSettleBatch(sheetId);
220	        List<Claim> batched = settled.stream().map(c -> {
221	            Claim claim = claims.lockByIdAndSheetId(c.getId(), sheetId).orElseThrow(ClaimNotFoundException::new);
222	            claim.setSettleBatch(batch);
223	            return claims.save(claim);
224	        }).toList();
225	        BigDecimal total = batched.stream()
226	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null)
227	                .map(Claim::getSettledDue)
228	                .reduce(BigDecimal.ZERO, BigDecimal::add)
229	                .setScale(2, RoundingMode.HALF_UP);
230	        audit.change("BATCH_SETTLED", sheetId, user, "batch=" + batch, "count=" + batched.size(),
231	                "total=" + total.toPlainString());
232	        return batched;
233	    }
