405	    /** Part-settle an OPEN claim: split {@code amount} off it as {@link #split} does, then settle the new
406	     * claim as {@link #changeStatus(String, String, long, ClaimStatus)} does (left PENDING when the clerk
407	     * limit says so). Who may settle and the proof rule are judged on the claim as it was before the split,
408	     * so the user, who opens the new claim, may still settle it. Refused, changing nothing, when the split
409	     * or the settle would be. Both claims are returned, the original first. */
410	    @Transactional
411	    public List<Claim> partSettle(String sheetId, String user, long claimId, BigDecimal amount) {
412	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
413	        if (!settings.allowed(sheetId, user, Action.SETTLE)) throw new ClaimNotStewardException();
414	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
415	            throw new ClaimStatusChangeException();
416	        }
417	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
418	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
419	                .orElseThrow(PersonNotFoundException::new);
420	        refuseUnproved(claim, person, rollup.shownOf(claim, person));
421	        List<Claim> split = split(sheetId, user, claimId, amount);
422	        Claim settled = changeStatus(sheetId, user, split.get(1).getId(), ClaimStatus.SETTLED, null, true, null);
423	        return List.of(split.get(0), settled);
424	    }
425	
426	    /** Move the claim to {@code next}; with {@code judged}, who may settle it and the proof rule have
427	     * already been judged (on the claim a part-settle split it from); a settle with {@code on} is as of
428	     * that date (see {@link #settle}). */
429	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
430	            boolean judged, LocalDate on) {
431	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
432	        Action action = switch (next) {
433	            case OPEN -> Action.OPEN;
434	            case SETTLED -> Action.SETTLE;
435	            case VOID -> Action.VOID;
436	            default -> null;
437	        };
438	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
439	        refuseClosed(sheetId, claim.getDueBy());
440	        if (!claim.getStatus().canBecome(next)
441	                || ((claim.getStatus() == ClaimStatus.PENDING || claim.getStatus() == ClaimStatus.REVIEW) && next != ClaimStatus.VOID)) {
442	            throw new ClaimStatusChangeException();
443	        }
444	        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
445	        if (reversing) refuseLateVoid(sheetId, user, claim);
446	        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
447	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
448	        if (next == ClaimStatus.SETTLED && !judged && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
449	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
450	                .orElseThrow(PersonNotFoundException::new);
451	        if (next == ClaimStatus.OPEN && person.isFlaggedOn(sheets.today(sheetId))
452	                && settings.roleOf(sheetId, user) != Role.STEWARD) {
453	            throw new ClaimNotStewardException();
454	        }
455	        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
456	        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
457	        if (next == ClaimStatus.OPEN) refuseOverMaxOpen(sheetId, claim);
458	        RollupService.Snapshot before = rollup.snapshot(sheetId);
459	        String number = claim.getNumber();
460	        if (next == ClaimStatus.OPEN && overReview(claim, person)) {
461	            next = ClaimStatus.REVIEW;
462	            claim.setOpenedBy(user);
463	        } else if (next == ClaimStatus.OPEN) {
464	            claim.setOpenedBy(user);
465	        }
466	        BigDecimal dueThen = null;
467	        if (next == ClaimStatus.SETTLED && on != null) {
468	            if (on.isAfter(sheets.today(sheetId))) throw new ClaimSettleDateException();
469	            SheetAsOf then = history.asOf(sheetId, on);
470	            Claim stood = then.claims().stream().filter(c -> c.getId().equals(claim.getId())).findFirst()
471	                    .orElseThrow(ClaimSettleDateException::new);
472	            Person personThen = then.person(person.getId()).orElseThrow(ClaimSettleDateException::new);
473	            dueThen = rollup.shownOf(stood, personThen, then);
474	        }
475	        if (next == ClaimStatus.SETTLED) {
476	            BigDecimal due = on == null ? rollup.shownOf(claim, person) : dueThen;
477	            if (!judged) refuseUnproved(claim, person, due);
478	            if (overLimit(sheetId, user, claim, person, due)) next = ClaimStatus.PENDING;
479	            else {
480	                claim.setSettledDue(due);
481	                if (number == null) number = nextNumber(sheetId, claim.getDueBy());
482	            }
483	        }
484	        claim.setStatus(next);
485	        claim.setNumber(number);
486	        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
487	        claims.flush();
488	        log(user, person, claim);
489	        String event = switch (next) {
490	            case OPEN -> "CLAIM_OPENED";
491	            case REVIEW -> "CLAIM_REVIEW";
492	            case PENDING -> "CLAIM_PENDING";
493	            case SETTLED -> "CLAIM_SETTLED";
494	            case VOID -> "CLAIM_VOIDED";
495	            case DRAFT, DELETED -> throw new IllegalStateException();
496	        };
497	        if (next == ClaimStatus.SETTLED) {
498	            List<String> extra = new ArrayList<>(List.of("due=" + dueText(claim.getSettledDue())));
499	            if (on != null) extra.add("on=" + on);
500	            record(event, user, person, claim, number, extra.toArray(String[]::new));
501	            notifyWatchers(user, person, claim);
502	        } else {
503	            List<String> extra = new ArrayList<>();
504	            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
505	            if (reason != null) extra.add("reason=" + reason);
506	            record(event, user, person, claim, number, extra.toArray(String[]::new));
507	        }
508	        rollup.recordSince(sheetId, user, before);
509	        return claim;
510	    }
