512	    /** Delete a DRAFT claim: it becomes DELETED, counts nowhere and cannot be edited, opened or voided
513	     * until it is restored. Refused unless the claim is a DRAFT, and when its due-by is in a closed period. */
514	    @Transactional
515	    public Claim delete(String sheetId, String user, long claimId) {
516	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
517	        refuseClosed(sheetId, claim.getDueBy());
518	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusChangeException();
519	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
520	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
521	                .orElseThrow(PersonNotFoundException::new);
522	        claim.setStatus(ClaimStatus.DELETED);
523	        claim.unlock();
524	        claims.flush();
525	        log(user, person, claim);
526	        record("CLAIM_DELETED", user, person, claim, claim.getNumber());
527	        return claim;
528	    }
529	
530	    /** Restore a DELETED claim: it is a DRAFT again. Refused unless the claim is DELETED, when the sheet's
531	     * today is not the day it was deleted (its status log's last DELETED date), and when its due-by is in
532	     * a closed period. */
533	    @Transactional
534	    public Claim restore(String sheetId, String user, long claimId) {
535	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
536	        refuseClosed(sheetId, claim.getDueBy());
537	        if (claim.getStatus() != ClaimStatus.DELETED) throw new ClaimStatusChangeException();
538	        LocalDate deleted = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
539	                .filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
540	                .map(ClaimLog::getDate)
541	                .reduce((first, second) -> second)
542	                .orElse(null);
543	        if (!sheets.today(sheetId).equals(deleted)) throw new ClaimRestoreLateException();
544	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
545	                .orElseThrow(PersonNotFoundException::new);
546	        claim.setStatus(ClaimStatus.DRAFT);
547	        claims.flush();
548	        log(user, person, claim);
549	        record("CLAIM_RESTORED", user, person, claim, claim.getNumber());
550	        return claim;
551	    }
552	
553	    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
554	     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
555	     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
556	     * when the claim is dated in a closed period. */
557	    @Transactional
558	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
559	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
560	        refuseClosed(sheetId, claim.getDueBy());
561	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
562	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
563	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
564	                .orElseThrow(PersonNotFoundException::new);
565	        RollupService.Snapshot before = rollup.snapshot(sheetId);
566	        claim.deferUntil(until);
567	        claims.flush();
568	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
569	        rollup.recordSince(sheetId, user, before);
570	        return claim;
571	    }
572	
573	    /** Hold an OPEN or PENDING claim that is not held, or release one that is: it still counts in
574	     * every total. Refused unless the claim is
575	     * OPEN or PENDING. */
576	    @Transactional
577	    public Claim toggleHold(String sheetId, String user, long claimId) {
578	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
579	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
580	            throw new ClaimStatusChangeException();
581	        }
582	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
583	                .orElseThrow(PersonNotFoundException::new);
584	        RollupService.Snapshot before = rollup.snapshot(sheetId);
585	        claim.setHeld(!claim.isHeld());
586	        claims.flush();
587	        record(claim.isHeld() ? "CLAIM_HELD" : "CLAIM_RELEASED", user, person, claim, claim.getNumber());
588	        rollup.recordSince(sheetId, user, before);
589	        return claim;
590	    }
591	
592	    /** A steward's waiver of an OPEN or PENDING claim's late charge: it bears none from then on, whatever
593	     * its overdue state. Refused when the user is not a steward, unless the claim is OPEN or PENDING, and
594	     * when it is already waived. */
595	    @Transactional
596	    public Claim waive(String sheetId, String user, long claimId) {
597	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
598	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
599	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
600	            throw new ClaimStatusChangeException();
601	        }
602	        if (claim.isWaived()) throw new ClaimWaivedException();
603	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
604	                .orElseThrow(PersonNotFoundException::new);
605	        RollupService.Snapshot before = rollup.snapshot(sheetId);
606	        claim.waive();
607	        claims.flush();
608	        record("CLAIM_WAIVED", user, person, claim, claim.getNumber());
609	        rollup.recordSince(sheetId, user, before);
610	        return claim;
611	    }
612	
613	    /** Remind an OPEN or PENDING claim: a reminder is written and the claim is reminded on the sheet's
614	     * today. Refused unless the claim is OPEN or PENDING, when it was already reminded on the sheet's
615	     * today, and when its due-by is in a closed period. A claim not yet escalated whose previous reminder was
616	     * at least the sheet's escalation gap before the sheet's today is escalated too, written after the reminder. */
617	    @Transactional
618	    public Claim remind(String sheetId, String user, long claimId) {
619	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
620	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
621	            throw new ClaimStatusChangeException();
622	        }
623	        LocalDate today = sheets.today(sheetId);
624	        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
625	        refuseClosed(sheetId, claim.getDueBy());
626	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
627	                .orElseThrow(PersonNotFoundException::new);
628	        Integer gap = settings.escalateAfter(sheetId);
629	        LocalDate previous = claim.getRemindedOn();
630	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
631	                && !previous.plusDays(gap).isAfter(today);
632	        claim.setRemindedOn(today);
633	        if (escalate) claim.setEscalated(true);
634	        claims.flush();
635	        record("REMIND", user, person, claim, claim.getNumber());
636	        if (escalate) record("ESCALATE", user, person, claim, claim.getNumber());
637	        return claim;
638	    }
639	
640	    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed,
641	     * so its period and number stay too, and a figure a statement bound it to stays bound. Refused when the
642	     * user is not a steward, unless the claim is OPEN or PENDING, when its due-by is in a closed period,
643	     * and when the new date is after its person's retirement date. */
644	    @Transactional
645	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
646	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
647	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
648	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
649	            throw new ClaimStatusChangeException();
650	        }
651	        refuseClosed(sheetId, claim.getDueBy());
652	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
653	                .orElseThrow(PersonNotFoundException::new);
654	        person.requireClaimable(date);
655	        RollupService.Snapshot before = rollup.snapshot(sheetId);
656	        LocalDate old = claim.getDate();
657	        claim.setDate(date);
658	        claims.flush();
659	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
660	        rollup.recordSince(sheetId, user, before);
661	        return claim;
662	    }
663	
664	    /** A steward's direct setting of a DRAFT, OPEN or PENDING claim's due-by to {@code dueBy}: it stays as
665	     * set (a holiday added later leaves it), and the claim's overdue state, late charge, grace and period
666	     * follow it. Refused when the user is not a steward, unless the claim is DRAFT, OPEN or PENDING, and
667	     * when its due-by or the new one is in a closed period. */
668	    @Transactional
669	    public Claim setDueBy(String sheetId, String user, long claimId, LocalDate dueBy) {
670	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
671	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
672	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
673	                && claim.getStatus() != ClaimStatus.PENDING) {
674	            throw new ClaimStatusChangeException();
675	        }
676	        refuseClosed(sheetId, claim.getDueBy());
677	        refuseClosed(sheetId, dueBy);
678	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
679	                .orElseThrow(PersonNotFoundException::new);
680	        RollupService.Snapshot before = rollup.snapshot(sheetId);
681	        LocalDate old = claim.getDueBy();
682	        claim.setDueByDirectly(dueBy);
683	        claims.flush();
684	        record("CLAIM_DUE_BY_SET", user, person, claim, claim.getNumber(), "old=" + old, "new=" + dueBy);
685	        rollup.recordSince(sheetId, user, before);
686	        return claim;
687	    }
688	
689	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
690	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
691	     * amount, with the same person, date and note, has no number until it is settled, is opened by the user, has
692	     * its due-by fixed now from its date and the terms in force on the sheet's today and names the claim's number as the one
693	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
694	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
695	     * in a closed period. Both claims are returned, the original first. */
696	    @Transactional
697	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
698	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
699	        refuseClosed(sheetId, claim.getDueBy());
700	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
701	            throw new ClaimStatusChangeException();
702	        }
703	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
704	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
705	                .orElseThrow(PersonNotFoundException::new);
706	        RollupService.Snapshot before = rollup.snapshot(sheetId);
707	        claim.setAmount(claim.getAmount().subtract(amount));
708	        claim.unbind();
709	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
710	        int terms = termsOf(sheetId, person, sheets.today(sheetId));
711	        split.fixTerms(claim.getDate(), terms);
712	        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
713	        refuseClosed(sheetId, split.getDueBy());
714	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
715	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
716	        split.setStatus(ClaimStatus.OPEN);
717	        split.setOpenedBy(user);
718	        split.setSplitFrom(claim.getNumber());
719	        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
720	        split = claims.saveAndFlush(split);
721	        log(user, person, split);
722	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + (split.getNumber() == null ? "" : split.getNumber()));
723	        record("CLAIM_OPENED", user, person, split, split.getNumber());
724	        rollup.recordSince(sheetId, user, before);
725	        return List.of(claim, split);
726	    }
727	
728	    /** A steward's review of a claim in REVIEW: it becomes OPEN, still with no number until it is
729	     * settled, keeping who opened it. Refused unless the claim is in REVIEW, when the user is not a steward, and
730	     * when its due-by is in a closed period. */
731	    @Transactional
732	    public Claim review(String sheetId, String user, long claimId) {
733	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
734	        refuseClosed(sheetId, claim.getDueBy());
735	        if (claim.getStatus() != ClaimStatus.REVIEW) throw new ClaimStatusChangeException();
736	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
737	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
738	                .orElseThrow(PersonNotFoundException::new);
739	        RollupService.Snapshot before = rollup.snapshot(sheetId);
740	        claim.setStatus(ClaimStatus.OPEN);
741	        claims.flush();
742	        log(user, person, claim);
743	        record("CLAIM_REVIEWED", user, person, claim, null);
744	        record("CLAIM_OPENED", user, person, claim, claim.getNumber());
745	        rollup.recordSince(sheetId, user, before);
746	        return claim;
747	    }
748	
749	    /** A steward's assignment of a claim in REVIEW to {@code assignee} to review. Refused unless the claim is
750	     * in REVIEW and when the user is not a steward. */
751	    @Transactional
752	    public Claim assignReview(String sheetId, String user, long claimId, String assignee) {
753	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
754	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
755	        if (claim.getStatus() != ClaimStatus.REVIEW) throw new ClaimStatusChangeException();
756	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
757	                .orElseThrow(PersonNotFoundException::new);
758	        claim.setReviewAssigned(assignee);
759	        claims.flush();
760	        record("REVIEW_ASSIGNED", user, person, claim, null, "user=" + assignee);
761	        return claim;
762	    }
763	
764	    /** A steward's (or the person's approver's) approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (as it
765	     * shows then: what a statement bound it to, late charge included, when one did, otherwise its person's rate then together with its late charge then).
766	     * It is given the next number then, unless it already has one.
767	     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
768	     * has no proofs and that due is above the proof threshold in force on its date. */
769	    @Transactional
770	    public Claim approve(String sheetId, String user, long claimId) {
771	        Claim claim = lockPending(sheetId, user, claimId);
772	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
773	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
774	                .orElseThrow(PersonNotFoundException::new);
775	        RollupService.Snapshot before = rollup.snapshot(sheetId);
776	        BigDecimal due = rollup.shownOf(claim, person);
777	        refuseUnproved(claim, person, due);
778	        claim.setSettledDue(due);
779	        claim.setStatus(ClaimStatus.SETTLED);
780	        if (claim.getNumber() == null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
781	        claims.flush();
782	        log(user, person, claim);
783	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
784	        notifyWatchers(user, person, claim);
785	        rollup.recordSince(sheetId, user, before);
786	        return claim;
787	    }
788	
789	    /** Raise the claim's proofs count by one, a proof of {@code kind} (receipt or photo; a receipt when
790	     * null, and the audit record then names no kind). Refused when the claim is SETTLED or VOID; a proof leaves
791	     * the claim's figures alone, so it may be added while the claim is dated in a closed period. */
792	    @Transactional
793	    public Claim addProof(String sheetId, String user, long claimId, String kind) {
794	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
795	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
796	                || claim.getStatus() == ClaimStatus.DELETED) {
797	            throw new ClaimStatusChangeException();
798	        }
799	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
800	                .orElseThrow(PersonNotFoundException::new);
801	        claim.addProof(kind == null ? Claim.RECEIPT : kind);
802	        claims.flush();
803	        if (kind == null) {
804	            record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
805	        } else {
806	            record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs(), "kind=" + kind);
807	        }
808	        return claim;
809	    }
810	
811	    /** A steward's (or the person's approver's) rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
812	     * by its person's last statement if that statement included it. Refused unless the claim is
813	     * PENDING, and when the user is not a steward. */
814	    @Transactional
815	    public Claim reject(String sheetId, String user, long claimId, String reason) {
816	        Claim claim = lockPending(sheetId, user, claimId);
817	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
818	                .orElseThrow(PersonNotFoundException::new);
819	        RollupService.Snapshot before = rollup.snapshot(sheetId);
820	        claim.setStatus(ClaimStatus.OPEN);
821	        claims.flush();
822	        log(user, person, claim);
823	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
824	        rollup.recordSince(sheetId, user, before);
825	        return claim;
826	    }
827	
828	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
829	     * date but, when it already has a number (one given before numbers were given at settlement), is given the next number in the sequence it is
830	     * numbered in (as when opened now), its old number never used again; it loses
831	     * any figure a statement bound it to (it is live again until its new person's next statement), and is listed as its new person's newest claim. Refused when the user's
832	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
833	     * own person) or already belongs to the person, when it is due by in a closed period, and when it
834	     * is dated after the new person's retirement date. */
835	    @Transactional
836	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
837	        return move(sheetId, user, claimId, personId, false);
838	    }
839	
840	    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
841	     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
842	     * and recorded). */
843	    @Transactional
844	    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
845	        return move(sheetId, user, claimId, personId, true);
846	    }
847	
848	    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
849	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
850	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
851	        refuseClosed(sheetId, claim.getDueBy());
852	        ClaimStatus status = claim.getStatus();
853	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
854	                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
855	            throw new ClaimReassignException();
856	        }
857	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
858	                .orElseThrow(PersonNotFoundException::new);
859	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
860	        to.requireClaimable(claim.getDate());
861	        RollupService.Snapshot before = rollup.snapshot(sheetId);
862	        claim.setPersonId(to.getId());
863	        claim.unbind();
864	        if (claim.getNumber() != null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
865	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
866	        claims.flush();
867	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
868	        rollup.recordSince(sheetId, user, before);
869	        return claim;
870	    }
871	
872	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
873	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
874	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
875	     * steward, and when it is dated in a closed period. */
876	    @Transactional
877	    public Claim resettle(String sheetId, String user, long claimId) {
878	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
879	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
880	        refuseClosed(sheetId, claim.getDueBy());
881	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
882	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
883	                .orElseThrow(PersonNotFoundException::new);
884	        RollupService.Snapshot before = rollup.snapshot(sheetId);
885	        BigDecimal old = claim.getSettledDue();
886	        BigDecimal due = rollup.openShownOf(claim, person);
887	        claim.setSettledDue(due);
888	        claims.flush();
889	        log(user, person, claim);
890	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
891	        notifyWatchers(user, person, claim);
892	        rollup.recordSince(sheetId, user, before);
893	        return claim;
894	    }
895	
896	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
897	     * 7 days after the date its status log first shows it SETTLED. */
898	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
899	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
900	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
901	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
902	                .map(ClaimLog::getDate)
903	                .findFirst()
904	                .orElseThrow(ClaimStatusChangeException::new);
905	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
906	    }
907	
908	    /** The PENDING claim, locked, for a steward or its person's approver to approve or reject. */
909	    private Claim lockPending(String sheetId, String user, long claimId) {
910	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
911	        refuseClosed(sheetId, claim.getDueBy());
912	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
913	        if (settings.roleOf(sheetId, user) != Role.STEWARD && !isApprover(sheetId, user, claim)) {
914	            throw new ClaimNotStewardException();
915	        }
916	        return claim;
917	    }
