/** The claims people on each sheet make. A claim left without a date is dated the sheet's entry date,
 * or its today when that is off. A claim's
 * terms are fixed when it is added, from those of its person's grade in force on its date, and its due-by
 * is the terms-th business day after that date, skipping weekends and the holidays on the sheet when it is added; the
 * claim belongs to the period containing that due-by (not its date). Only a DRAFT claim can be edited.
 * No claim whose due-by falls inside a closed period (not only soft-closed) can be added, edited or
 * change status, nor be edited to a date whose due-by, with its terms, would; one added with its due-by inside a soft-closed period is a late entry, and none can be added or edited to a date after its person's retirement date. A claim with a
 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
 * person, and for no more than what remains of it (its amount less the corrections already made against
 * it, VOID and DELETED ones left out); a claim that is not a correction names none. A DRAFT claim may have lines (see {@link ClaimLine}):
 * then its amount is what they add up to, and an edit to any other amount is refused. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final ClaimCommentRepository comments;
    private final ClaimLineRepository lines;
    private final ClaimShareRepository shares;
    private final PersonRepository people;
    private final RollupService rollup;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final PersonWatchRepository watches;
    private final HolidayService holidays;
    private final Audit audit;
    private final SheetTagRepository tagRepository;
    private final VoidReasonService voidReasons;
    private final SheetHistory history;

    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
            PeriodRepository periods, SettingsService settings, PersonWatchRepository watches, HolidayService holidays,
            Audit audit, SheetTagRepository tagRepository, VoidReasonService voidReasons,
            ClaimCommentRepository comments, ClaimLineRepository lines, ClaimShareRepository shares,
            SheetHistory history) {
        this.history = history;
        this.shares = shares;
        this.comments = comments;
        this.lines = lines;
        this.voidReasons = voidReasons;
        this.tagRepository = tagRepository;
        this.holidays = holidays;
        this.watches = watches;
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rollup = rollup;
        this.sheets = sheets;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /** The sheet's duplicate claims: for each person, date and amount with two or more claims (VOID and
     * DELETED ones left out), one line {@code <name> <date> <amount> x<count>}; people in list order, then
     * by date, then by amount. */
    @Transactional(readOnly = true)
    public List<String> duplicates(String sheetId) {
        record Key(LocalDate date, BigDecimal amount) {}
        Map<Long, Map<Key, Long>> counts = claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
                .collect(Collectors.groupingBy(Claim::getPersonId, Collectors.groupingBy(
                        c -> new Key(c.getDate(), c.getAmount().setScale(2, RoundingMode.UNNECESSARY)),
                        Collectors.counting())));
        List<String> out = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            counts.getOrDefault(person.getId(), Map.of()).entrySet().stream()
                    .filter(e -> e.getValue() >= 2)
                    .sorted(Map.Entry.<Key, Long>comparingByKey(Comparator.comparing(Key::date)
                            .thenComparing(Key::amount)))
                    .forEach(e -> out.add(person.getName() + " " + e.getKey().date() + " "
                            + e.getKey().amount().toPlainString() + " x" + e.getValue()));
        }
        return out;
    }

    /** The status logs of the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
    }

    /** The day a REVIEW claim's review day must be before for it to be late: the sheet's today less its
     * review SLA; null when the sheet has no review SLA. */
    @Transactional(readOnly = true)
    public LocalDate reviewLateBefore(String sheetId) {
        Integer sla = settings.reviewSla(sheetId);
        return sla == null ? null : sheets.today(sheetId).minusDays(sla);
    }

    /** The day a PENDING claim's pending day must be before for it to be late: the sheet's today less its
     * pending SLA; null when the sheet has no pending SLA. */
    @Transactional(readOnly = true)
    public LocalDate pendingLateBefore(String sheetId) {
        Integer sla = settings.pendingSla(sheetId);
        return sla == null ? null : sheets.today(sheetId).minusDays(sla);
    }

    /** The comments on the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimComment>> commentsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return comments.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimComment::getClaimId));
    }

    /** The lines of the claims, by claim id, each in the order they were added. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLine>> linesOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return lines.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLine::getClaimId));
    }

    /** The shares of each of the claims, in the order they were given, by claim id. */
    public Map<Long, List<ClaimShare>> sharesOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return shares.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimShare::getClaimId));
    }

    /** Share the claim with another person on the sheet: they hold {@code share} percent (more than 0.00)
     * of what is due on it. Refused when the person is the claim's own, already holds a share of it, when
     * its shares would total more than 100.00, and when the claim is SETTLED, VOID or DELETED. */
    @Transactional
    public Claim share(String sheetId, String user, long claimId, long personId, BigDecimal share) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                || claim.getStatus() == ClaimStatus.DELETED) {
            throw new ClaimShareException();
        }
        Person holder = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (share.signum() <= 0 || holder.getId().equals(claim.getPersonId())) throw new ClaimShareException();
        List<ClaimShare> held = shares.findByClaimIdOrderByIdAsc(claim.getId());
        if (held.stream().anyMatch(s -> s.getPersonId().equals(holder.getId()))) throw new ClaimShareException();
        BigDecimal total = held.stream().map(ClaimShare::getShare).reduce(share, BigDecimal::add);
        if (total.compareTo(BigDecimal.valueOf(100)) > 0) throw new ClaimShareException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        ClaimShare given = shares.saveAndFlush(new ClaimShare(sheetId, claim.getId(), holder.getId(), share));
        record("CLAIM_SHARED", user, person, claim, null, "with=" + holder.getName(), "share=" + given.shareText());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Add a line to a DRAFT claim: {@code label} (not blank), {@code qty} (at least 1) of {@code unit}
     * each; the claim's amount becomes its lines' quantities times their unit amounts, added up. It counts
     * as an edit of the claim. Refused when the claim is not a DRAFT, when its due-by is in a closed period
     * and when another user's editor holds its lock. */
    @Transactional
    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        lines.saveAndFlush(new ClaimLine(claim.getId(), label, qty, unit.setScale(2)));
        List<ClaimLine> all = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
        BigDecimal total = ClaimLine.totalOf(all);
        if (total.precision() - total.scale() > 10) throw new ClaimLinedAmountException();
        claim.setAmount(total);
        claim.setEditedBy(user);
        claims.flush();
        ClaimLine line = all.get(all.size() - 1);
        record("CLAIM_LINE_ADDED", user, person, claim, claim.getNumber(), "label=" + line.getLabel(),
                "qty=" + line.getQty(), "unit=" + line.unitText());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Make the claims, settled (or left PENDING) by one bulk settle, the sheet's next settle batch,
     * returning them with its number, in the order given; records BATCH_SETTLED with the batch's number,
     * how many claims it has and the frozen figures of those SETTLED added up. */
    @Transactional
    public List<Claim> settleBatch(String sheetId, String user, List<Claim> settled) {
        int batch = sheets.nextSettleBatch(sheetId);
        List<Claim> batched = settled.stream().map(c -> {
            Claim claim = claims.lockByIdAndSheetId(c.getId(), sheetId).orElseThrow(ClaimNotFoundException::new);
            claim.setSettleBatch(batch);
            return claims.save(claim);
        }).toList();
        BigDecimal total = batched.stream()
                .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null)
                .map(Claim::getSettledDue)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
        audit.change("BATCH_SETTLED", sheetId, user, "batch=" + batch, "count=" + batched.size(),
                "total=" + total.toPlainString());
        return batched;
    }

    /** Comment on the claim, whatever its status: {@code text} (not blank) is kept with the user and the
     * sheet's today. */
    @Transactional
    public Claim comment(String sheetId, String user, long claimId, String text) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        comments.save(new ClaimComment(claim.getId(), user, sheets.today(sheetId), text));
        record("COMMENT_ADDED", user, person, claim, claim.getNumber(), "text=" + text);
        return claim;
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

    /** Every tag ever used on the sheet's claims, sorted. */
    @Transactional(readOnly = true)
    public List<String> tags(String sheetId) {
        return tagRepository.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
    }

    /** Add a claim with the external reference {@code ref} (none when null), refused when another claim
     * on the sheet has it (compared without regard to case), and the tags {@code tags} (see
     * {@link Claim#tagsOf}; none when null). */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
        int terms = termsOf(sheetId, person, person.gradeOn(dated), sheets.today(sheetId));
        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
        refuseClosed(sheetId, dueBy);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, personId, null, amount, corrects);
        refuseRefTaken(sheetId, null, ref);
        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
        claim.setRef(ref);
        claim.setTags(tags);
        claim.fixTerms(dated, terms);
        claim.setDueBy(dueBy);
        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
        claim = claims.saveAndFlush(claim);
        log(user, person, claim);
        keepTags(claim);
        List<String> extra = new ArrayList<>();
        if (ref != null) extra.add("ref=" + ref);
        if (tags != null) extra.add("tags=" + tags);
        record("CLAIM_ADDED", user, person, claim, claim.getNumber(), extra.toArray(String[]::new));
        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    @Transactional
    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
        refuseClosed(sheetId, claim.getDueBy());
        refuseClosed(sheetId, holidays.dueBy(sheetId, dated, claim.getTerms()));
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, person.getId(), claim.getId(), amount, corrects);
        refuseRefTaken(sheetId, claim.getId(), ref);
        List<ClaimLine> lined = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
        if (!lined.isEmpty() && ClaimLine.totalOf(lined).compareTo(amount) != 0) throw new ClaimLinedAmountException();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setDate(dated);
        claim.setNote(noteOf(note));
        claim.setRef(ref);
        claim.setTags(tags);
        claim.setEditedBy(user);
        keepTags(claim);
        claim.unlock();
        claims.flush();
        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Edit the claim's amount to {@code amount} as the claim form would, keeping its date, note,
     * correction, reference and tags, when it is a DRAFT; one in any other status is left as it is.
     * Refused as {@link #update} refuses. Records CLAIM_EDITED. */
    @Transactional
    public Claim editDraftAmount(String sheetId, String user, long claimId, BigDecimal amount) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.DRAFT) return claim;
        return update(sheetId, user, claimId, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
                claim.getRef(), claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
    }

    /** Open the claim's editor for {@code user}, locking the claim for everyone else until it is saved
     * (see {@link #update}) or cancelled (see {@link #unlock}), or the sheet's today changes. Refused,
     * taking no lock, when the claim cannot be edited (not a DRAFT, or dated in a closed period) or
     * another user holds its lock. */
    @Transactional
    public Claim lock(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        LocalDate today = sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        if (claim.isLockedFor(user, today)) throw new ClaimLockedException();
        claim.lock(user, today);
        return claim;
    }

    /** Close {@code user}'s editor of the claim without saving, releasing the lock it holds; a lock
     * another user holds is left alone. */
    @Transactional
    public Claim unlock(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (user.equals(claim.getLockedBy())) claim.unlock();
        return claim;
    }

    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
     * on it as it shows then (what a statement bound it to, late charge included, when one did, otherwise its
     * person's rate then together with its late charge then, none on a correction); the user who opened it or last edited it
     * cannot settle it,
     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
     * is recorded as reversed. A claim is given its number when it is settled (the next in the sequence it is
 * numbered in, by its due-by, unless it already has one), not when opened; a voided claim keeps its number, if it had one. An open of a claim whose due
 * is above the review threshold in force on its date leaves it in REVIEW instead, opened by the user but
 * until a steward reviews it (see {@link #review}); a REVIEW claim can only be voided
 * here. While the claim's person is flagged on the sheet's today, only a steward may open it. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
        return changeStatus(sheetId, user, claimId, next, null);
    }

    /** Move the claim to {@code next} as {@link #changeStatus(String, String, long, ClaimStatus)} does;
     * a void is given {@code voidReason}, which while the sheet's list of void reasons is not empty must
     * be one on it (see {@link VoidReasonService#refuseUnlisted}), and is kept on the claim. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
        return changeStatus(sheetId, user, claimId, next, voidReason, false, null);
    }

    /** Settle the claim as {@link #changeStatus(String, String, long, ClaimStatus)} does, but as of
     * {@code on} (now when null): the figure fixed is its due as it stood at the end of that date, worked
     * out as the sheet's as-of view does (see {@link SheetHistory#asOf}), and CLAIM_SETTLED ends with the
     * date. Refused when the date is after the sheet's today, and when the claim had not been added then. */
    @Transactional
    public Claim settle(String sheetId, String user, long claimId, LocalDate on) {
        return changeStatus(sheetId, user, claimId, ClaimStatus.SETTLED, null, false, on);
    }

    /** Part-settle an OPEN claim: split {@code amount} off it as {@link #split} does, then settle the new
     * claim as {@link #changeStatus(String, String, long, ClaimStatus)} does (left PENDING when the clerk
     * limit says so). Who may settle and the proof rule are judged on the claim as it was before the split,
     * so the user, who opens the new claim, may still settle it. Refused, changing nothing, when the split
     * or the settle would be. Both claims are returned, the original first. */
    @Transactional
    public List<Claim> partSettle(String sheetId, String user, long claimId, BigDecimal amount) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (!settings.allowed(sheetId, user, Action.SETTLE)) throw new ClaimNotStewardException();
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ClaimStatusChangeException();
        }
        if (claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        refuseUnproved(claim, person, rollup.shownOf(claim, person));
        List<Claim> split = split(sheetId, user, claimId, amount);
        Claim settled = changeStatus(sheetId, user, split.get(1).getId(), ClaimStatus.SETTLED, null, true, null);
        return List.of(split.get(0), settled);
    }

    /** Move the claim to {@code next}; with {@code judged}, who may settle it and the proof rule have
     * already been judged (on the claim a part-settle split it from); a settle with {@code on} is as of
     * that date (see {@link #settle}). */
    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
            boolean judged, LocalDate on) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Action action = switch (next) {
            case OPEN -> Action.OPEN;
            case SETTLED -> Action.SETTLE;
            case VOID -> Action.VOID;
            default -> null;
        };
        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
        refuseClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(next)
                || ((claim.getStatus() == ClaimStatus.PENDING || claim.getStatus() == ClaimStatus.REVIEW) && next != ClaimStatus.VOID)) {
            throw new ClaimStatusChangeException();
        }
        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
        if (reversing) refuseLateVoid(sheetId, user, claim);
        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
        if (next == ClaimStatus.SETTLED && !judged && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (next == ClaimStatus.OPEN && person.isFlaggedOn(sheets.today(sheetId))
                && settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimNotStewardException();
        }
        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
        if (next == ClaimStatus.OPEN) refuseOverMaxOpen(sheetId, claim);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String number = claim.getNumber();
        if (next == ClaimStatus.OPEN && overReview(claim, person)) {
            next = ClaimStatus.REVIEW;
            claim.setOpenedBy(user);
        } else if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
        BigDecimal dueThen = null;
        if (next == ClaimStatus.SETTLED && on != null) {
            if (on.isAfter(sheets.today(sheetId))) throw new ClaimSettleDateException();
            SheetAsOf then = history.asOf(sheetId, on);
            Claim stood = then.claims().stream().filter(c -> c.getId().equals(claim.getId())).findFirst()
                    .orElseThrow(ClaimSettleDateException::new);
            Person personThen = then.person(person.getId()).orElseThrow(ClaimSettleDateException::new);
            dueThen = rollup.shownOf(stood, personThen, then);
        }
        if (next == ClaimStatus.SETTLED) {
            BigDecimal due = on == null ? rollup.shownOf(claim, person) : dueThen;
            if (!judged) refuseUnproved(claim, person, due);
            if (overLimit(sheetId, user, claim, person, due)) next = ClaimStatus.PENDING;
            else {
                claim.setSettledDue(due);
                if (number == null) number = nextNumber(sheetId, claim.getDueBy());
            }
        }
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
        claims.flush();
        log(user, person, claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case REVIEW -> "CLAIM_REVIEW";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        if (next == ClaimStatus.SETTLED) {
            List<String> extra = new ArrayList<>(List.of("due=" + dueText(claim.getSettledDue())));
            if (on != null) extra.add("on=" + on);
            record(event, user, person, claim, number, extra.toArray(String[]::new));
            notifyWatchers(user, person, claim);
        } else {
            List<String> extra = new ArrayList<>();
            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
            if (reason != null) extra.add("reason=" + reason);
            record(event, user, person, claim, number, extra.toArray(String[]::new));
        }
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Delete a DRAFT claim: it becomes DELETED, counts nowhere and cannot be edited, opened or voided
     * until it is restored. Refused unless the claim is a DRAFT, and when its due-by is in a closed period. */
    @Transactional
    public Claim delete(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusChangeException();
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.setStatus(ClaimStatus.DELETED);
        claim.unlock();
        claims.flush();
        log(user, person, claim);
        record("CLAIM_DELETED", user, person, claim, claim.getNumber());
        return claim;
    }

    /** Restore a DELETED claim: it is a DRAFT again. Refused unless the claim is DELETED, when the sheet's
     * today is not the day it was deleted (its status log's last DELETED date), and when its due-by is in
     * a closed period. */
    @Transactional
    public Claim restore(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DELETED) throw new ClaimStatusChangeException();
        LocalDate deleted = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
                .filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
                .map(ClaimLog::getDate)
                .reduce((first, second) -> second)
                .orElse(null);
        if (!sheets.today(sheetId).equals(deleted)) throw new ClaimRestoreLateException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.setStatus(ClaimStatus.DRAFT);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_RESTORED", user, person, claim, claim.getNumber());
        return claim;
    }

    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
     * when the claim is dated in a closed period. */
    @Transactional
    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.deferUntil(until);
        claims.flush();
        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Hold an OPEN or PENDING claim that is not held, or release one that is: it still counts in
     * every total. Refused unless the claim is
     * OPEN or PENDING. */
    @Transactional
    public Claim toggleHold(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusChangeException();
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setHeld(!claim.isHeld());
        claims.flush();
        record(claim.isHeld() ? "CLAIM_HELD" : "CLAIM_RELEASED", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** A steward's waiver of an OPEN or PENDING claim's late charge: it bears none from then on, whatever
     * its overdue state. Refused when the user is not a steward, unless the claim is OPEN or PENDING, and
     * when it is already waived. */
    @Transactional
    public Claim waive(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusChangeException();
        }
        if (claim.isWaived()) throw new ClaimWaivedException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.waive();
        claims.flush();
        record("CLAIM_WAIVED", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Remind an OPEN or PENDING claim: a reminder is written and the claim is reminded on the sheet's
     * today. Refused unless the claim is OPEN or PENDING, when it was already reminded on the sheet's
     * today, and when its due-by is in a closed period. A claim not yet escalated whose previous reminder was
     * at least the sheet's escalation gap before the sheet's today is escalated too, written after the reminder. */
    @Transactional
    public Claim remind(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusChangeException();
        }
        LocalDate today = sheets.today(sheetId);
        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
        refuseClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        Integer gap = settings.escalateAfter(sheetId);
        LocalDate previous = claim.getRemindedOn();
        boolean escalate = gap != null && previous != null && !claim.isEscalated()
                && !previous.plusDays(gap).isAfter(today);
        claim.setRemindedOn(today);
        if (escalate) claim.setEscalated(true);
        claims.flush();
        record("REMIND", user, person, claim, claim.getNumber());
        if (escalate) record("ESCALATE", user, person, claim, claim.getNumber());
        return claim;
    }

    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed,
     * so its period and number stay too, and a figure a statement bound it to stays bound. Refused when the
     * user is not a steward, unless the claim is OPEN or PENDING, when its due-by is in a closed period,
     * and when the new date is after its person's retirement date. */
    @Transactional
    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusChangeException();
        }
        refuseClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        person.requireClaimable(date);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate old = claim.getDate();
        claim.setDate(date);
        claims.flush();
        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** A steward's direct setting of a DRAFT, OPEN or PENDING claim's due-by to {@code dueBy}: it stays as
     * set (a holiday added later leaves it), and the claim's overdue state, late charge, grace and period
     * follow it. Refused when the user is not a steward, unless the claim is DRAFT, OPEN or PENDING, and
     * when its due-by or the new one is in a closed period. */
    @Transactional
    public Claim setDueBy(String sheetId, String user, long claimId, LocalDate dueBy) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
                && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusChangeException();
        }
        refuseClosed(sheetId, claim.getDueBy());
        refuseClosed(sheetId, dueBy);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate old = claim.getDueBy();
        claim.setDueByDirectly(dueBy);
        claims.flush();
        record("CLAIM_DUE_BY_SET", user, person, claim, claim.getNumber(), "old=" + old, "new=" + dueBy);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
     * amount, with the same person, date and note, has no number until it is settled, is opened by the user, has
     * its due-by fixed now from its date and the terms in force on the sheet's today and names the claim's number as the one
     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
     * in a closed period. Both claims are returned, the original first. */
    @Transactional
    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ClaimStatusChangeException();
        }
        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(claim.getAmount().subtract(amount));
        claim.unbind();
        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
        int terms = termsOf(sheetId, person, sheets.today(sheetId));
        split.fixTerms(claim.getDate(), terms);
        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
        refuseClosed(sheetId, split.getDueBy());
        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
        split.setListed(sheets.nextInSequence(sheetId, "listed"));
        split.setStatus(ClaimStatus.OPEN);
        split.setOpenedBy(user);
        split.setSplitFrom(claim.getNumber());
        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
        split = claims.saveAndFlush(split);
        log(user, person, split);
        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + (split.getNumber() == null ? "" : split.getNumber()));
        record("CLAIM_OPENED", user, person, split, split.getNumber());
        rollup.recordSince(sheetId, user, before);
        return List.of(claim, split);
    }

    /** A steward's review of a claim in REVIEW: it becomes OPEN, still with no number until it is
     * settled, keeping who opened it. Refused unless the claim is in REVIEW, when the user is not a steward, and
     * when its due-by is in a closed period. */
    @Transactional
    public Claim review(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.REVIEW) throw new ClaimStatusChangeException();
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setStatus(ClaimStatus.OPEN);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_REVIEWED", user, person, claim, null);
        record("CLAIM_OPENED", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** A steward's assignment of a claim in REVIEW to {@code assignee} to review. Refused unless the claim is
     * in REVIEW and when the user is not a steward. */
    @Transactional
    public Claim assignReview(String sheetId, String user, long claimId, String assignee) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        if (claim.getStatus() != ClaimStatus.REVIEW) throw new ClaimStatusChangeException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.setReviewAssigned(assignee);
        claims.flush();
        record("REVIEW_ASSIGNED", user, person, claim, null, "user=" + assignee);
        return claim;
    }

    /** A steward's (or the person's approver's) approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (as it
     * shows then: what a statement bound it to, late charge included, when one did, otherwise its person's rate then together with its late charge then).
     * It is given the next number then, unless it already has one.
     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
     * has no proofs and that due is above the proof threshold in force on its date. */
    @Transactional
    public Claim approve(String sheetId, String user, long claimId) {
        Claim claim = lockPending(sheetId, user, claimId);
        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal due = rollup.shownOf(claim, person);
        refuseUnproved(claim, person, due);
        claim.setSettledDue(due);
        claim.setStatus(ClaimStatus.SETTLED);
        if (claim.getNumber() == null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
        claims.flush();
        log(user, person, claim);
        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
        notifyWatchers(user, person, claim);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Raise the claim's proofs count by one, a proof of {@code kind} (receipt or photo; a receipt when
     * null, and the audit record then names no kind). Refused when the claim is SETTLED or VOID; a proof leaves
     * the claim's figures alone, so it may be added while the claim is dated in a closed period. */
    @Transactional
    public Claim addProof(String sheetId, String user, long claimId, String kind) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                || claim.getStatus() == ClaimStatus.DELETED) {
            throw new ClaimStatusChangeException();
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.addProof(kind == null ? Claim.RECEIPT : kind);
        claims.flush();
        if (kind == null) {
            record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
        } else {
            record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs(), "kind=" + kind);
        }
        return claim;
    }

    /** A steward's (or the person's approver's) rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
     * by its person's last statement if that statement included it. Refused unless the claim is
     * PENDING, and when the user is not a steward. */
    @Transactional
    public Claim reject(String sheetId, String user, long claimId, String reason) {
        Claim claim = lockPending(sheetId, user, claimId);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setStatus(ClaimStatus.OPEN);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
     * date but, when it already has a number (one given before numbers were given at settlement), is given the next number in the sequence it is
     * numbered in (as when opened now), its old number never used again; it loses
     * any figure a statement bound it to (it is live again until its new person's next statement), and is listed as its new person's newest claim. Refused when the user's
     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
     * own person) or already belongs to the person, when it is due by in a closed period, and when it
     * is dated after the new person's retirement date. */
    @Transactional
    public Claim reassign(String sheetId, String user, long claimId, long personId) {
        return move(sheetId, user, claimId, personId, false);
    }

    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
     * and recorded). */
    @Transactional
    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
        return move(sheetId, user, claimId, personId, true);
    }

    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
        refuseClosed(sheetId, claim.getDueBy());
        ClaimStatus status = claim.getStatus();
        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
            throw new ClaimReassignException();
        }
        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        to.requireClaimable(claim.getDate());
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setPersonId(to.getId());
        claim.unbind();
        if (claim.getNumber() != null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
        claims.flush();
        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
     * steward, and when it is dated in a closed period. */
    @Transactional
    public Claim resettle(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal old = claim.getSettledDue();
        BigDecimal due = rollup.openShownOf(claim, person);
        claim.setSettledDue(due);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
        notifyWatchers(user, person, claim);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
     * 7 days after the date its status log first shows it SETTLED. */
    private void refuseLateVoid(String sheetId, String user, Claim claim) {
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
                .map(ClaimLog::getDate)
                .findFirst()
                .orElseThrow(ClaimStatusChangeException::new);
        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
    }

    /** The PENDING claim, locked, for a steward or its person's approver to approve or reject. */
    private Claim lockPending(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
        if (settings.roleOf(sheetId, user) != Role.STEWARD && !isApprover(sheetId, user, claim)) {
            throw new ClaimNotStewardException();
        }
        return claim;
    }

    /** Whether {@code user} is the approver of the claim's person. */
    private boolean isApprover(String sheetId, String user, Claim claim) {
        return people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .map(Person::getApprover)
                .filter(user::equals)

