    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
     * the person, or that exceeds what remains of it: its amount less the corrections already made
     * against it (other than {@code claimId}, the one being edited; VOID and DELETED ones left out); and
     * a claim that names one without being a correction. */
    private void refuseBadCorrection(String sheetId, Long personId, Long claimId, BigDecimal amount,
            String corrects) {
        if (amount.signum() >= 0) {
            if (corrects != null) throw new ClaimCorrectionException();
            return;
        }
        if (corrects == null) throw new ClaimCorrectionException();
        Claim corrected = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
                .filter(target -> target.getStatus() == ClaimStatus.SETTLED)
                .orElseThrow(ClaimCorrectionException::new);
        BigDecimal remains = corrected.getAmount();
        for (Claim made : claims.findBySheetIdAndPersonIdAndCorrects(sheetId, personId, corrects)) {
            if (made.getId().equals(claimId) || made.getStatus() == ClaimStatus.VOID
                    || made.getStatus() == ClaimStatus.DELETED) continue;
            remains = remains.add(made.getAmount());
        }
        if (amount.negate().compareTo(remains) > 0) throw new ClaimCorrectionException();
    }

    /** Refuse the external reference {@code ref} when a claim on the sheet other than {@code claimId} has
     * it, compared without regard to case. */
    private void refuseRefTaken(String sheetId, Long claimId, String ref) {
        if (ref == null) return;
        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
                .filter(other -> !other.getId().equals(claimId))
                .ifPresent(other -> {
                    throw new ClaimRefTakenException();
                });
    }

    /** Refuse opening the claim when the period its due-by falls in caps its person's OPEN or PENDING
     * claims in it, and they already have that many. The period is locked until the transaction ends,
     * so two claims are never opened past its cap at once. */
    /** Refuse opening the claim when its person already has the sheet's maximum of OPEN or PENDING claims. */
    private void refuseOverMaxOpen(String sheetId, Claim claim) {
        Integer max = settings.maxOpen(sheetId);
        if (max == null) return;
        long open = claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> !c.getId().equals(claim.getId()) && c.getPersonId().equals(claim.getPersonId())
                        && c.getStatus().isOpen())
                .count();
        if (open >= max) throw new ClaimMaxOpenException();
    }

    private void refuseOverCap(String sheetId, Claim claim) {
        LocalDate dueBy = claim.getDueBy();
        Period capped = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(p -> p.getCap() != null && p.overlaps(dueBy, dueBy)).findFirst().orElse(null);
        if (capped == null) return;
        Period period = periods.lockByIdAndSheetId(capped.getId(), sheetId).orElseThrow();
        long open = claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> !c.getId().equals(claim.getId()) && c.getPersonId().equals(claim.getPersonId())
                        && c.getStatus().isOpen() && c.getDueBy() != null && period.overlaps(c.getDueBy(), c.getDueBy()))
                .count();
        if (open >= period.getCap()) throw new ClaimCapException();
    }

    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
    private void refuseClosed(String sheetId, LocalDate date) {
        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }

    /** The terms a claim of the person created on {@code date} (the sheet's today then) is due by: the person's own terms
     * in force on that day, else those of their grade in force on that day, else the sheet's then. */
    private int termsOf(String sheetId, Person person, LocalDate date) {
        return termsOf(sheetId, person, person.gradeOn(date), date);
    }

    /** The terms as {@link #termsOf(String, Person, LocalDate)} gives them, but judged for the person's
     * {@code grade} (the one they have on the claim's date). */
    private int termsOf(String sheetId, Person person, String grade, LocalDate date) {
        Integer own = person.termsOn(date);
        return own != null ? own : settings.termsFor(sheetId, grade, date);
    }
