113	            sharesByClaim.computeIfAbsent(share.getClaimId(), k -> new ArrayList<>()).add(share);
114	        }
115	        Map<Long, Person> byId = new LinkedHashMap<>();
116	        for (Person person : everyone) byId.put(person.getId(), person);
117	        Map<Long, BigDecimal> heldParts = new LinkedHashMap<>();
118	        for (Claim claim : all) {
119	            List<ClaimShare> held = sharesByClaim.get(claim.getId());
120	            Person owner = byId.get(claim.getPersonId());
121	            if (held == null || owner == null || !countsLive(claim, owner, today)) continue;
122	            BigDecimal figure = shownOf(claim, owner, basis);
123	            if (figure == null) continue;
124	            for (ClaimShare share : held) {
125	                BigDecimal part = partOf(claim, share, figure, byId.get(share.getPersonId()), basis);
126	                if (part != null) heldParts.merge(share.getPersonId(), part, BigDecimal::add);
127	            }
128	        }
129	        for (Person person : everyone) {
130	            BigDecimal claimed = zero();
131	            BigDecimal due = zero();
132	            BigDecimal overdue = zero();
133	            BigDecimal settled = zero();
134	            BigDecimal open = zero();
135	            boolean any = false;
136	            for (Claim claim : all) {
137	                if (!claim.getPersonId().equals(person.getId())) continue;
138	                if (countsClaimed(claim, person, today) && !claim.isCorrection()) claimed = claimed.add(claim.getAmount());
139	                if (!countsLive(claim, person, today)) continue;
140	                BigDecimal figure = shownOf(claim, person, basis);
141	                if (figure == null) continue;
142	                if (isOverdue(claim, basis)) overdue = overdue.add(figure);
143	                if (claim.getStatus().isOpen()) open = open.add(figure);
144	                else settled = settled.add(figure);
145	                due = due.add(ownPartOf(claim, figure, sharesByClaim.get(claim.getId()), byId, basis));
146	                any = true;
147	            }
148	            BigDecimal part = heldParts.get(person.getId());
149	            if (part != null) {
150	                due = due.add(part);
151	                any = true;
152	            }
153	            BigDecimal cut = basis.cutOf(person.getId());
154	            due = cappedOf(due, capOf(all, person, basis), cut);
155	            boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
156	            claimedTotal = claimedTotal.add(claimed);
157	            overdueFigures.add(overdue);
158	            if (any || rated) dueFigures.add(due);
159	            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE,
160	                    text(overdue), text(settled), text(open), text(cut == null ? zero() : cut)));
161	        }
162	        return new Snapshot(figures, text(claimedTotal), text(trimmedSum(dueFigures)), text(trimmedSum(overdueFigures)));
163	    }
