165	    /** What is left of {@code figure} to the claim's own person once the holders of its {@code shares}
166	     * (none when null), from {@code byId}, have their parts (see {@link #partOf}). */
167	    private static BigDecimal ownPartOf(Claim claim, BigDecimal figure, List<ClaimShare> shares,
168	            Map<Long, Person> byId, Basis basis) {
169	        if (shares == null) return figure;
170	        BigDecimal own = figure;
171	        for (ClaimShare share : shares) {
172	            BigDecimal part = partOf(claim, share, figure, byId.get(share.getPersonId()), basis);
173	            if (part != null) own = own.subtract(part);
174	        }
175	        return own;
176	    }
