178	    /** The {@code holder}'s part of the claim whose figure is {@code figure} by their {@code share}: on a claim
179	     * showing the figure fixed when it was settled, that figure's part (see {@link ClaimShare#partOf}); otherwise
180	     * the claim's amount times the share divided by 100, times the rate of the holder's own grade in force on
181	     * the claim's date divided by 100, rounded as the claim rounds (see {@link #roundingOf}). Null (0.00) when
182	     * the holder's grade has no rate then, or the holder is gone. */
183	    private static BigDecimal partOf(Claim claim, ClaimShare share, BigDecimal figure, Person holder, Basis basis) {
184	        if (frozen(claim)) return share.partOf(figure);
185	        if (holder == null) return null;
186	        RoundingMode rounding = roundingOf(claim, basis);
187	        return basis.rateFor(claim, holder.gradeOn(claim.getDate()), claim.getDate())
188	                .map(Rate::getPct)
189	                .map(pct -> claim.getAmount().multiply(share.getShare()).multiply(pct).movePointLeft(4)
190	                        .setScale(2, rounding))
191	                .orElse(null);
192	    }
