194	    /** Each person's score on the sheet as it stands, by person, in list order: their settled-total (what is due
195	     * on their counting SETTLED claims that are not corrections, as each shows it, before the cap) divided by 100, minus 5 for every
196	     * counting claim of theirs that is overdue, rounded half to even to a whole number. */
197	    @Transactional(propagation = Propagation.MANDATORY)
198	    public Map<Long, Score> scores(String sheetId) {
199	        Basis basis = live(sheetId);
200	        LocalDate today = basis.today();
201	        List<Claim> all = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
202	        Map<Long, Score> scores = new LinkedHashMap<>();
203	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
204	            BigDecimal settled = zero();
205	            int overdue = 0;
206	            for (Claim claim : all) {
207	                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person, today)) continue;
208	                if (isOverdue(claim, basis)) overdue++;
209	                if (claim.getStatus().isOpen() || claim.isCorrection()) continue;
210	                BigDecimal figure = shownOf(claim, person, basis);
211	                if (figure != null) settled = settled.add(figure);
212	            }
213	            BigDecimal score = settled.movePointLeft(2).subtract(BigDecimal.valueOf(5L * overdue))
214	                    .setScale(0, RoundingMode.HALF_EVEN);
215	            scores.put(person.getId(), new Score(person.getName(), score.toPlainString()));
216	        }
217	        return scores;
218	    }
