224	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
225	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
226	        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
227	        if (figures.size() < 3) return sum;
228	        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
229	    }
