231	    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
232	    @Transactional(propagation = Propagation.MANDATORY)
233	    public void recordSince(String sheetId, String user, Snapshot before) {
234	        Snapshot after = snapshot(sheetId);
235	        after.people().forEach((id, now) -> {
236	            Figures then = before.people().get(id);
237	            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())
238	                    && then.overdueTotal().equals(now.overdueTotal())) return;
239	            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
240	                    "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal());
241	        });
242	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
243	                || !Objects.equals(before.dueTotal(), after.dueTotal())
244	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
245	            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
246	                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal());
247	        }
248	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
249	        if (threshold == null) return;
250	        after.people().forEach((id, now) -> {
251	            Figures then = before.people().get(id);
252	            if (above(now.dueTotal(), threshold) && (then == null || !above(then.dueTotal(), threshold))) {
253	                audit.change("ALERT", sheetId, user, "name=" + now.name(), "due-total=" + now.dueTotal());
254	            }
255	        });
256	    }
