258	    /** Whether a due-total as shown is above the threshold (n/a never is). */
259	    private static boolean above(String dueTotal, BigDecimal threshold) {
260	        return !NONE.equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
261	    }
