263	    /** Whether the claim is overdue on {@code basis}: OPEN or PENDING, not deferred on its today, and
264	     * overdue from a date before it (its due-by plus any grace, see {@link Basis#overdueFrom}). */
265	    public static boolean isOverdue(Claim claim, Basis basis) {
266	        LocalDate today = basis.today();
267	        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
268	                && !claim.isDeferredOn(today) && basis.overdueFrom(claim).isBefore(today);
269	    }
