271	    /** A due-total as shown: at most {@code cap} less the person's cut total {@code cut}, not below 0.00, when
272	     * there is a cap. */
273	    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap, BigDecimal cut) {
274	        return cap == null ? due : due.min(cap.subtract(cut).max(zero()));
