277	    /** Whether the claim counts in the live totals on the sheet's {@code today}: OPEN, PENDING or
278	     * SETTLED, but not a claim deferred on {@code today} (see {@link Claim#isDeferredOn}), nor OPEN or PENDING when its person's
279	     * retirement date is reached on {@code today} and no statement binds it. A hold, the person's or the
280	     * claim's own, does not take it out. */
281	    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
282	        return countsAs(claim, claim.getStatus(), person, today);
283	    }
