291	    /** Whether the claim would count in the live totals on the sheet's {@code today} were its status
292	     * {@code status} (see {@link #countsLive}). */
293	    public static boolean countsAs(Claim claim, ClaimStatus status, Person person, LocalDate today) {
294	        if (!status.counts()) return false;
295	        if (claim.getStatus() == ClaimStatus.SETTLED && claim.isDeferredOn(today)) return false;
296	        if (!status.isOpen()) return true;
297	        if (claim.isDeferredOn(today)) return false;
298	        return claim.isStated() || !person.isRetiredOn(today);
299	    }
