301	    /** What a sheet's figures are worked out from: its today, the policy date, rates and dated settings in
302	     * force, and its claims. {@link #live} is the sheet as it stands; a sheet as it stood on an earlier
303	     * date gives its own. */
304	    public interface Basis {
305	
306	        /** The sheet's today; null when there is no sheet. */
307	        LocalDate today();
308	
309	        /** The policy date in force (see {@link Sheet#policyDateInForce()}); null when there is no sheet. */
310	        LocalDate policyDateInForce();
311	
312	        /** The grade's rate in force on the date (see {@link RateRepository#findInForce}), or else the
313	         * nearest parent sheet's (see {@link RateChain}). */
314	        Optional<Rate> rateInForce(String grade, LocalDate date);
315	
316	        /** The grade's rate in force on the date for the claim (see {@link RateRepository#inForce(java.util.List,
317	         * String, LocalDate, long)}): a rate saved forward-only after the claim was added does not apply to it. */
318	        Optional<Rate> rateFor(Claim claim, String grade, LocalDate date);
319	
320	        /** The floor in force on the date; 0.00 when there is no sheet. */
321	        BigDecimal floorOn(LocalDate date);
322	
323	        /** The late percent in force on the date. */
324	        BigDecimal latePctOn(LocalDate date);
325	
326	        /** The cap in force on the date; null when there is none then. */
327	        BigDecimal capOn(LocalDate date);
328	
329	        /** The person's cut total: their cuts across every pool they are a member of, added up; 0.00 by default. */
330	        default BigDecimal cutOf(Long personId) {
331	            return zero();
332	        }
333	
334	        /** The person's claim with the number. */
335	        Optional<Claim> claimNumbered(Long personId, String number);
336	
337	        /** The person with the id. */
338	        Optional<Person> personOf(Long personId);
339	
340	        /** The grade's grace days in force on the date; null when it has none then. */
341	        Integer graceOn(String grade, LocalDate date);
342	
343	        /** The shares of the sheet's claims, in the order they were given; none by default. */
344	        default List<ClaimShare> shares() {
345	            return List.of();
346	        }
347	
348	        /** The rounding mode in force on the date; null when there is none then. */
349	        RoundingMode roundingOn(LocalDate date);
350	
351	        /** The date a claim's lateness counts from: its due-by plus the grace days in force on the claim's
352	         * date of its person's grade in force then (its due-by when that grade has none). */
353	        default LocalDate overdueFrom(Claim claim) {
354	            LocalDate dueBy = claim.getDueBy();
355	            if (dueBy == null) return null;
356	            Integer grace = personOf(claim.getPersonId()).map(p -> p.gradeOn(claim.getDate()))
357	                    .map(grade -> graceOn(grade, claim.getDate())).orElse(null);
358	            return grace == null ? dueBy : dueBy.plusDays(grace);
359	        }
360	    }
