542	    /** The person's due-total on {@code basis} from those of {@code theirs} that count on its today (see
543	     * {@link #countsLive}): the sum of what is due on them as each shows it, at most the cap less their cut total; null (n/a)
544	     * when none has a figure and no rate of their grade is in force on its today. */
545	    public BigDecimal dueTotalOf(List<Claim> theirs, Person person, Basis basis) {
546	        LocalDate today = basis.today();
547	        BigDecimal due = zero();
548	        boolean any = false;
549	        for (Claim claim : theirs) {
550	            if (!countsLive(claim, person, today)) continue;
551	            BigDecimal figure = shownOf(claim, person, basis);
552	            if (figure == null) continue;
553	            due = due.add(figure);
554	            any = true;
555	        }
556	        boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
557	        return any || rated ? cappedOf(due, capOf(theirs, person, basis), basis.cutOf(person.getId())) : null;
558	    }
