561	     * {@link #capDateOf}) from {@code all}; null when there is none then. */
562	    public static BigDecimal capOf(List<Claim> all, Person person, Basis basis) {
563	        LocalDate on = capDateOf(all, person, basis.today());
564	        return on == null ? null : basis.capOn(on);
