567	    /** The date a person's cap is taken on: the latest date of their own claims among {@code all} that count
568	     * on the sheet's {@code today} (see {@link #countsLive}); its today when none does; null when there is no
569	     * sheet. */
570	    public static LocalDate capDateOf(List<Claim> all, Person person, LocalDate today) {
571	        if (today == null) return null;
572	        LocalDate latest = null;
573	        for (Claim claim : all) {
574	            if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person, today)) continue;
575	            if (latest == null || claim.getDate().isAfter(latest)) latest = claim.getDate();
576	        }
577	        return latest == null ? today : latest;
578	    }
