625	    private BigDecimal liveDueOf(Claim claim, BigDecimal figure, Basis basis) {
626	        if (figure == null) return null;
627	        if (claim.isCorrection()) return figure;
628	        BigDecimal floored = floored(claim, figure, basis);
629	        return floored.add(lateChargeOf(claim, floored, basis));
