641	    /** {@code due}, at least the sheet's floor in force on the claim's date. */
642	    private static BigDecimal floored(Claim claim, BigDecimal due, Basis basis) {
643	        return due.max(basis.floorOn(claim.getDate()));
644	    }
645	
646	    /** The late charge on an OPEN or PENDING claim whose figure is {@code figure}: for every full 30 days the claim is overdue (past its due-by, fixed when it was added, plus
647	     * any grace of its grade (see {@link Basis#overdueFrom}), on the sheet's today), the sheet's late percent
648	     * in force on that boundary date (that date plus 30, 60, 90 ... days) of that figure plus the charges of the boundaries before it (compounding), rounded to two decimals as the claim rounds, the charges added up (a boundary whose percent is 0.00 adds nothing) (see {@link #roundingOf}); 0.00 on a claim not OPEN or
649	     * PENDING, or not overdue (a deferred claim is not), on a correction and on a waived claim. A claim a statement binds shows the charge it had then instead (see {@link #shownOf}). */
650	    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
651	        return lateChargeOf(claim, figure, live(claim.getSheetId()));
652	    }
653	
654	    private BigDecimal lateChargeOf(Claim claim, BigDecimal figure, Basis basis) {
655	        if (!claim.getStatus().isOpen()) return zero();
656	        return overdueChargeOf(claim, figure, basis);
657	    }
658	
659	    /** What would be due on the claim now were it an OPEN claim bound by no statement: its due at its
660	     * person's rate (see {@link #dueOf}), at least the sheet's floor in force on its date, plus the late
661	     * charge it would have then on that floored figure (a correction has neither); null when it would
662	     * have no figure. */
663	    public BigDecimal openShownOf(Claim claim, Person person) {
664	        Basis basis = live(claim.getSheetId());
665	        BigDecimal figure = dueOf(claim, person, basis);
666	        if (figure == null || claim.isCorrection()) return figure;
667	        BigDecimal floored = floored(claim, figure, basis);
668	        return floored.add(overdueChargeOf(claim, floored, basis));
669	    }
670	
671	    /** The late charge on a claim whose figure is {@code figure}, whatever its status (see {@link #lateChargeOf}). */
672	    private BigDecimal overdueChargeOf(Claim claim, BigDecimal figure, Basis basis) {
673	        if (claim.isCorrection() || claim.isWaived()) return zero();
674	        LocalDate today = basis.today();
675	        if (today == null || claim.isDeferredOn(today)) return zero();
676	        LocalDate from = basis.overdueFrom(claim);
677	        long periods = Math.max(0, ChronoUnit.DAYS.between(from, today)) / 30;
678	        RoundingMode rounding = roundingOf(claim, basis);
679	        BigDecimal charge = zero();
680	        for (long k = 1; k <= periods; k++) {
681	            BigDecimal pct = basis.latePctOn(from.plusDays(30 * k));
682	            if (pct.signum() == 0) continue;
683	            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
684	        }
685	        return charge;
686	    }
687	
688	    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
689	     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}) — the rate
690	     * figure alone, before any late charge or floor (see {@link #liveDueOf}); null when no
691	     * rate of the grade in force for them on the claim's date applies then. */
692	    public BigDecimal dueOf(Claim claim, Person person) {
693	        return dueOf(claim, person, live(claim.getSheetId()));
694	    }
695	
696	    private BigDecimal dueOf(Claim claim, Person person, Basis basis) {
697	        RoundingMode rounding = roundingOf(claim, basis);
698	        return basis.rateFor(claim, person.gradeOn(claim.getDate()), claim.getDate())
699	                .map(Rate::getPct)
700	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
701	                .orElse(null);
702	    }
703	
704	    /** How the claim's live figures round: by the rounding mode in force on its date when there is one;
705	     * else half up when it is dated before the sheet's policy date in force, half to even when on or
706	     * after it. A correction rounds by the date of the claim it corrects. */
707	    private static RoundingMode roundingOf(Claim claim, Basis basis) {
708	        LocalDate dated = claim.getDate();
709	        if (claim.isCorrection() && claim.getCorrects() != null) {
710	            dated = basis.claimNumbered(claim.getPersonId(), claim.getCorrects()).map(Claim::getDate).orElse(dated);
711	        }
712	        RoundingMode mode = basis.roundingOn(dated);
713	        if (mode != null) return mode;
714	        LocalDate policyDate = basis.policyDateInForce();
715	        if (policyDate == null) return RoundingMode.HALF_EVEN;
716	        return dated.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
717	    }
718	
719	    private static BigDecimal zero() {
720	        return BigDecimal.ZERO.setScale(2);
721	    }
722	
723	    private static String text(BigDecimal value) {
724	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
725	    }
726	}
